    elif human_resources_manager.knowledge_of_hr_practices == "needs_improvement":
        score += 1

    # Evaluate age (middle age is preferred)
    if human_resources_manager.age == "middle":
        score += 3
    elif human_resources_manager.age == "young":
        score += 2
    elif human_resources_manager.age == "elder":
