    Evaluate a human resources manager based on various attributes.

    Args:
        manager (object): An instance with attributes: age, interpersonal_skills, knowledge_of_hr_practices, ethical_judgment, leadership_abilities

    Returns:
        int: A score based on the manager's attributes.
    """
    score = 0

    # Evaluate age
    if manager.age == 'middle':
        score += 2
    elif manager.age in ['young', 'elder']:
        score += 1

    # Evaluate interpersonal skills
    if manager.interpersonal_skills >= 8:
        score += 2
    elif manager.interpersonal_skills >= 5:
        score += 1

    # Evaluate knowledge of HR practices
    if manager.knowledge_of_hr_practices == 'excellent':
        score += 2
    elif manager.knowledge_of_hr_practices == 'good':
        score += 1

    # Evaluate ethical judgment
    if manager.ethical_judgment == 'excellent':
        score += 2
    elif manager.ethical_judgment == 'good':
        score += 1

    # Evaluate leadership abilities
    if manager.leadership_abilities == 'strong':
        score += 2
    elif manager.leadership_abilities == 'average':
        score += 1

    return score

def evaluate_human_resources_manager(manager):
    """
    Evaluates a human resources manager based on their attributes and returns a score.

    Args:
        manager (object): A human_resources_manager object with the following attributes:
            - age (young, middle, elder)
            - leadership_abilities (excellent, good, fair)
            - interpersonal_skills (excellent, good, average)
            - knowledge_of_hr_practices (excellent, good, average)
            - ethical_judgment (excellent, good, fair)

    Returns:
        int: The total score based on the manager's attributes.
    """
    score = 0

    # Evaluate age
    if manager.age == 'middle' or manager.age == 'elder':
        score += 2
    elif manager.age == 'young':
        score += 1

    # Evaluate leadership abilities
    if manager.leadership_abilities == 'excellent':
        score += 3
    elif manager.leadership_abilities == 'good':
        score += 2
    elif manager.leadership_abilities == 'fair':
        score += 1

    # Evaluate interpersonal skills
    if manager.interpersonal_skills == 'excellent':
        score += 3
    elif manager.interpersonal_skills == 'good':
        score += 2
    elif manager.interpersonal_skills == 'average':
        score += 1

    # Evaluate knowledge of HR practices
    if manager.knowledge_of_hr_practices == 'excellent':
        score += 3
    elif manager.knowledge_of_hr_practices == 'good':
        score += 2
    elif manager.knowledge_of_hr_practices == 'average':
        score += 1

    # Evaluate ethical judgment
    if manager.ethical_judgment == 'excellent':
        score += 3
    elif manager.ethical_judgment == 'good':
        score += 2
    elif manager.ethical_judgment == 'fair':
        score += 1

    return score

